from selenium.webdriver.common.by import By
from taf.selenium.sc.pages.menu import Menu
from taf.selenium.sc.pages.modals import OverwirteRecentEditedConfigurationModal


class ConfigurationMenu(Menu):
    _SECONDE_LEVEL_MENU = '//div[text()="{}"]//ancestor::div[@class="card-container"]//button'
    _SECONDE_MENU_INDEX = 1
    _THIRD_MENU_INDEX = 2
    _ACTIVE_BUTTON_ON_EDIT_CONFIGURATION = '//button[contains(@class, "active")]'
    _EDIT = 'Edit'

    def __init__(self, driver):
        super(ConfigurationMenu, self).__init__(driver)
        self._driver = driver
        self._overwrite_conf_modal = OverwirteRecentEditedConfigurationModal(driver)

    def open_page(self, menu_list):
        menu_xpath_list = [self._MAIN_MENU_XPATH.format(menu_list[self.FIRST_MENU_INDEX]),
                           self._SECONDE_LEVEL_MENU.format(menu_list[self.SECOND_MENU_INDEX]),
                           menu_list[self._THIRD_MENU_INDEX]]

        if self._is_page_active(menu_list):
            return

        for index, xpath in enumerate(menu_xpath_list):
            self.click_enabled_element_after_visible((By.XPATH, xpath))
            if index == self.SECOND_MENU_INDEX and self._overwrite_conf_modal.wait_until_overwrite_conf_modal_appear(3):
                self._overwrite_conf_modal.overwrite()

    def _is_page_active(self, menu_list):
        elems = self.driver.find_elements_by_xpath(menu_list[self._THIRD_MENU_INDEX])

        if elems and menu_list[self._SECONDE_MENU_INDEX] == self._EDIT:
            attr = self.get_attribute_by_xpath(menu_list[self._THIRD_MENU_INDEX], 'class')
            if 'active' not in attr:
                self.click_enabled_element_after_visible((By.XPATH, menu_list[self._THIRD_MENU_INDEX]))
            return True

        if elems:
            return True

        return False
